import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import CandidateForm, { CandidateRow } from '@/components/CandidateForm';

const mockCandidate: CandidateRow = {
  _id: 'cand1',
  name: '김후보',
  birth_year: '1990',
  current_affiliation: 'KAIST',
  current_position: '조교수',
  major_field: '컴퓨터공학',
  total_papers: '30',
  jcr_ratio: '15',
  fwci: '2.0',
  remarks: '',
  degrees: [],
  careers: [],
};

describe('CandidateForm 컴포넌트', () => {
  it('후보자가 없을 때 "후보자가 없습니다." 메시지 표시', () => {
    render(<CandidateForm candidates={[]} onCandidatesChange={jest.fn()} />);
    expect(screen.getByText('후보자가 없습니다. 후보자를 추가해주세요.')).toBeInTheDocument();
  });

  it('후보자 추가 버튼 클릭 시 onCandidatesChange 호출', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[]} onCandidatesChange={onChange} />);
    fireEvent.click(screen.getByText('+ 후보자 추가'));
    expect(onChange).toHaveBeenCalledTimes(1);
    const newCandidates = onChange.mock.calls[0][0];
    expect(newCandidates).toHaveLength(1);
    expect(newCandidates[0]).toHaveProperty('name', '');
  });

  it('후보자가 있을 때 이름이 input에 표시됨', () => {
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={jest.fn()} />);
    const inputs = screen.getAllByDisplayValue('김후보');
    expect(inputs.length).toBeGreaterThan(0);
  });

  it('후보자 삭제 버튼 클릭 시 해당 후보자 제거', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={onChange} />);
    const deleteButtons = screen.getAllByTitle('행 삭제');
    fireEvent.click(deleteButtons[0]);
    expect(onChange).toHaveBeenCalledWith([]);
  });

  it('학위/경력 아코디언: 클릭하면 학위 섹션이 표시됨', () => {
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={jest.fn()} />);
    const accordionButton = screen.getByText(/김후보/);
    fireEvent.click(accordionButton);
    expect(screen.getByText('최종학위')).toBeInTheDocument();
    expect(screen.getByText('경력 사항')).toBeInTheDocument();
  });

  it('아코디언 다시 클릭하면 닫힘', () => {
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={jest.fn()} />);
    const accordionButton = screen.getByText(/김후보/);
    fireEvent.click(accordionButton);
    expect(screen.getByText('최종학위')).toBeInTheDocument();
    fireEvent.click(accordionButton);
    expect(screen.queryByText('최종학위')).not.toBeInTheDocument();
  });

  it('아코디언 열린 후 학위 추가 버튼 클릭', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={onChange} />);
    fireEvent.click(screen.getByText(/김후보/));
    fireEvent.click(screen.getByText('+ 학위 추가'));
    expect(onChange).toHaveBeenCalled();
    const updated = onChange.mock.calls[onChange.mock.calls.length - 1][0] as CandidateRow[];
    expect(updated[0].degrees).toHaveLength(1);
  });

  it('아코디언 열린 후 경력 추가 버튼 클릭', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={onChange} />);
    fireEvent.click(screen.getByText(/김후보/));
    fireEvent.click(screen.getByText('+ 경력 추가'));
    expect(onChange).toHaveBeenCalled();
    const updated = onChange.mock.calls[onChange.mock.calls.length - 1][0] as CandidateRow[];
    expect(updated[0].careers).toHaveLength(1);
  });

  it('여러 후보자가 있을 때 각 후보자 이름 표시', () => {
    const candidates = [
      { ...mockCandidate, _id: 'c1', name: '후보자A' },
      { ...mockCandidate, _id: 'c2', name: '후보자B' },
    ];
    render(<CandidateForm candidates={candidates} onCandidatesChange={jest.fn()} />);
    expect(screen.getAllByDisplayValue('후보자A').length).toBeGreaterThan(0);
    expect(screen.getAllByDisplayValue('후보자B').length).toBeGreaterThan(0);
  });
});

