     1→import { NextRequest, NextResponse } from 'next/server';
     2→import db from '@/lib/db';
     3→import type { SubmissionInput, SubmissionRow } from '@/lib/types';
     4→import * as XLSX from 'xlsx';
     5→
     6→export async function POST(request: NextRequest) {
     7→  let body: SubmissionInput;
     8→
     9→  try {
    10→    body = await request.json();
    11→  } catch {
    12→    return NextResponse.json({ error: '잘못된 요청 형식입니다.' }, { status: 400 });
    13→  }
    14→
    15→  const { department_name, dean_name, submitted_at, candidates, hiringProgress } = body;
    16→
    17→  if (!department_name || !dean_name || !submitted_at) {
    18→    return NextResponse.json(
    19→      { error: '필수 필드가 누락되었습니다. (department_name, dean_name, submitted_at)' },
    20→      { status: 400 }
    21→    );
    22→  }
    23→
    24→  try {
    25→    const insertSubmission = db.prepare(
    26→      `INSERT INTO submissions (department_name, dean_name, submitted_at) VALUES (?, ?, ?)`
    27→    );
    28→    const insertCandidate = db.prepare(
    29→      `INSERT INTO candidates (submission_id, name, birth_year, current_affiliation, current_position, major_field, total_papers, jcr_ratio, fwci, remarks)
    30→       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    31→    );
    32→    const insertDegree = db.prepare(
    33→      `INSERT INTO candidate_degrees (candidate_id, school, major, degree_year, degree_type)
    34→       VALUES (?, ?, ?, ?, ?)`
    35→    );
    36→    const insertCareer = db.prepare(
    37→      `INSERT INTO candidate_careers (candidate_id, institution, position, period)
    38→       VALUES (?, ?, ?, ?)`
    39→    );
    40→    const insertProgress = db.prepare(
    41→      `INSERT INTO hiring_progress (submission_id, progress_date, content, person_in_charge)
    42→       VALUES (?, ?, ?, ?)`
    43→    );
    44→
    45→    const runTransaction = db.transaction(() => {
    46→      const submissionResult = insertSubmission.run(department_name, dean_name, submitted_at);
    47→      const submissionId = submissionResult.lastInsertRowid as number;
    48→
    49→      for (const candidate of candidates ?? []) {
    50→        if (!candidate.name) continue;
    51→        const candidateResult = insertCandidate.run(
    52→          submissionId,
    53→          candidate.name,
    54→          candidate.birth_year ?? null,
    55→          candidate.current_affiliation ?? null,
    56→          candidate.current_position ?? null,
    57→          candidate.major_field ?? null,
    58→          candidate.total_papers ?? null,
    59→          candidate.jcr_ratio ?? null,
    60→          candidate.fwci ?? null,
    61→          candidate.remarks ?? null
    62→        );
    63→        const candidateId = candidateResult.lastInsertRowid as number;
    64→
    65→        for (const degree of candidate.degrees ?? []) {
    66→          insertDegree.run(
    67→            candidateId,
    68→            degree.school ?? null,
    69→            degree.major ?? null,
    70→            degree.degree_year ?? null,
    71→            degree.degree_type ?? null
    72→          );
    73→        }
    74→
    75→        for (const career of candidate.careers ?? []) {
    76→          insertCareer.run(
    77→            candidateId,
    78→            career.institution ?? null,
    79→            career.position ?? null,
    80→            career.period ?? null
    81→          );
    82→        }
    83→      }
    84→
    85→      for (const progress of hiringProgress ?? []) {
    86→        insertProgress.run(
    87→          submissionId,
    88→          progress.progress_date ?? null,
    89→          progress.content ?? null,
    90→          progress.person_in_charge ?? null
    91→        );
    92→      }
    93→
    94→      return submissionId;
    95→    });
    96→
    97→    const id = runTransaction();
    98→
    99→    return NextResponse.json({ id, message: '제출 완료' }, { status: 201 });
   100→  } catch (error) {
   101→    console.error('POST /api/submissions error:', error);
   102→    return NextResponse.json(
   103→      { error: '서버 오류가 발생했습니다.', detail: String(error) },
   104→      { status: 500 }
   105→    );
   106→  }
   107→}
   108→
   109→export async function GET(request: NextRequest) {
   110→  const { searchParams } = new URL(request.url);
   111→  const format = searchParams.get('format');
   112→
   113→  try {
   114→    const rows = db
   115→      .prepare(
   116→        `SELECT s.*, COUNT(c.id) as candidate_count
   117→         FROM submissions s
   118→         LEFT JOIN candidates c ON c.submission_id = s.id
   119→         GROUP BY s.id
   120→         ORDER BY s.created_at DESC`
   121→      )
   122→      .all() as SubmissionRow[];
   123→
   124→    if (format === 'excel') {
   125→      const candidateRows = db
   126→        .prepare(
   127→          `SELECT c.*, s.department_name, s.dean_name, s.submitted_at
   128→           FROM candidates c
   129→           JOIN submissions s ON s.id = c.submission_id
   130→           ORDER BY s.id, c.id`
   131→        )
   132→        .all();
   133→
   134→      const wb = XLSX.utils.book_new();
   135→
   136→      const sheet1Data = rows.map((r) => ({
   137→        ID: r.id,
   138→        학과명: r.department_name,
   139→        학장명: r.dean_name,
   140→        제출일시: r.submitted_at,
   141→        상태: r.status,
   142→        후보자수: r.candidate_count ?? 0,
   143→        생성일시: r.created_at,
   144→      }));
