     5→interface Params {
     6→  params: { id: string };
     7→}
     8→
     9→export async function GET(_request: NextRequest, { params }: Params) {
    10→  const id = parseInt(params.id, 10);
    11→
    12→  if (isNaN(id)) {
    13→    return NextResponse.json({ error: '유효하지 않은 ID입니다.' }, { status: 400 });
    14→  }
    15→
    16→  try {
    17→    const submission = db
    18→      .prepare(`SELECT * FROM submissions WHERE id = ?`)
    19→      .get(id) as SubmissionRow | undefined;
    20→
    21→    if (!submission) {
    22→      return NextResponse.json({ error: '해당 제출 데이터를 찾을 수 없습니다.' }, { status: 404 });
    23→    }
    24→
    25→    type CandidateRow = {
    26→      id: number;
    27→      submission_id: number;
    28→      name: string;
    29→      birth_year?: number;
    30→      current_affiliation?: string;
    31→      current_position?: string;
    32→      major_field?: string;
    33→      total_papers?: number;
    34→      jcr_ratio?: number;
    35→      fwci?: number;
    36→      remarks?: string;
    37→      created_at?: string;
    38→    };
    39→
    40→    type DegreeRow = {
    41→      id: number;
    42→      candidate_id: number;
    43→      school?: string;
    44→      major?: string;
    45→      degree_year?: number;
    46→      degree_type?: string;
    47→    };
    48→
    49→    type CareerRow = {
    50→      id: number;
    51→      candidate_id: number;
    52→      institution?: string;
    53→      position?: string;
    54→      period?: string;
    55→    };
    56→
    57→    type ProgressRow = {
    58→      id: number;
    59→      submission_id: number;
    60→      progress_date?: string;
    61→      content?: string;
    62→      person_in_charge?: string;
    63→    };
    64→
    65→    const candidateRows = db
    66→      .prepare(`SELECT * FROM candidates WHERE submission_id = ? ORDER BY id`)
    67→      .all(id) as CandidateRow[];
    68→
    69→    const candidates = candidateRows.map((candidate) => {
    70→      const degrees = db
    71→        .prepare(`SELECT * FROM candidate_degrees WHERE candidate_id = ? ORDER BY id`)
    72→        .all(candidate.id) as DegreeRow[];
    73→
    74→      const careers = db
    75→        .prepare(`SELECT * FROM candidate_careers WHERE candidate_id = ? ORDER BY id`)
    76→        .all(candidate.id) as CareerRow[];
    77→
    78→      return {
    79→        id: candidate.id,
    80→        name: candidate.name,
    81→        birth_year: candidate.birth_year,
    82→        current_affiliation: candidate.current_affiliation,
    83→        current_position: candidate.current_position,
    84→        major_field: candidate.major_field,
    85→        total_papers: candidate.total_papers,
    86→        jcr_ratio: candidate.jcr_ratio,
    87→        fwci: candidate.fwci,
    88→        remarks: candidate.remarks,
    89→        degrees: degrees.map((d) => ({
    90→          school: d.school,
    91→          major: d.major,
    92→          degree_year: d.degree_year,
    93→          degree_type: d.degree_type,
    94→        })),
    95→        careers: careers.map((c) => ({
    96→          institution: c.institution,
    97→          position: c.position,
    98→          period: c.period,
    99→        })),
   100→      };
   101→    });
   102→
   103→    const hiringProgress = (
   104→      db
   105→        .prepare(
   106→          `SELECT * FROM hiring_progress WHERE submission_id = ? ORDER BY id`
   107→        )
   108→        .all(id) as ProgressRow[]
   109→    ).map((p) => ({
   110→      progress_date: p.progress_date,
   111→      content: p.content,
   112→      person_in_charge: p.person_in_charge,
   113→    }));
   114→
   115→    const detail: SubmissionDetail = {
   116→      ...submission,
   117→      candidates,
   118→      hiringProgress,
   119→    };
   120→
   121→    return NextResponse.json(detail);
   122→  } catch (error) {
   123→    console.error(`GET /api/submissions/${id} error:`, error);
   124→    return NextResponse.json(
   125→      { error: '서버 오류가 발생했습니다.', detail: String(error) },
   126→      { status: 500 }
   127→    );
   128→  }
   129→}
