    19→}
    20→
    21→export interface CandidateRow {
    22→  _id: string;
    23→  name: string;
    24→  birth_year: string;
    25→  current_affiliation: string;
    26→  current_position: string;
    27→  major_field: string;
    28→  total_papers: string;
