    34→}
    35→
    36→interface CandidateFormProps {
    37→  candidates: CandidateRow[];
    38→  onCandidatesChange: (candidates: CandidateRow[]) => void;
    39→}
    40→
    41→const generateId = () => Math.random().toString(36).substr(2, 9);
    42→
    43→const candidateColumns: ColumnDef<Omit<CandidateRow, 'degrees' | 'careers'> & { _id: string }>[] = [
    44→  { key: 'name', label: '성명', type: 'text', width: '80px' },
    45→  { key: 'birth_year', label: '출생년도', type: 'text', width: '80px' },
    46→  { key: 'current_affiliation', label: '현소속', type: 'text' },
