    54→
    55→const degreeColumns: ColumnDef<DegreeRow>[] = [
    56→  { key: 'school', label: '학교명', type: 'text' },
    57→  { key: 'major', label: '전공', type: 'text' },
    58→  { key: 'degree_year', label: '취득년도', type: 'text', width: '90px' },
    59→  { key: 'degree_type', label: '학위구분', type: 'text', width: '90px' },
    60→];
    61→
    62→const careerColumns: ColumnDef<CareerRow>[] = [
    63→  { key: 'institution', label: '기관명', type: 'text' },
    64→  { key: 'position', label: '직위', type: 'text' },
