    81→
    82→  const addCandidate = () => {
    83→    const newCandidate: CandidateRow = {
    84→      _id: generateId(),
    85→      name: '',
    86→      birth_year: '',
    87→      current_affiliation: '',
    88→      current_position: '',
    89→      major_field: '',
    90→      total_papers: '',
    91→      jcr_ratio: '',
    92→      fwci: '',
    93→      remarks: '',
    94→      degrees: [],
    95→      careers: [],
    96→    };
    97→    onCandidatesChange([...candidates, newCandidate]);
    98→  };
    99→
   100→  const deleteCandidate = (id: string) => {
