   157→      ...c,
   158→      careers: c.careers.filter((ca) => ca._id !== careerId),
   159→    }));
   160→  };
   161→
   162→  const updateCareer = (candidateId: string, careerId: string, key: keyof CareerRow, value: string) => {
   163→    updateCandidateNested(candidateId, (c) => ({
   164→      ...c,
   165→      careers: c.careers.map((ca) => (ca._id === careerId ? { ...ca, [key]: value } : ca)),
