import { GET } from '@/app/api/submissions/[id]/route';

function makeRequest(id: string): NextRequest {
  return new NextRequest(`http://localhost/api/submissions/${id}`);
}

describe('GET /api/submissions/[id]', () => {
  it('존재하는 id → 상세 데이터 반환', async () => {
    const req = makeRequest('1');
    const res = await GET(req, { params: { id: '1' } });
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json).toHaveProperty('id');
    expect(json).toHaveProperty('candidates');
    expect(json).toHaveProperty('hiringProgress');
  });

  it('숫자가 아닌 id → 400 에러', async () => {
    const req = makeRequest('abc');
    const res = await GET(req, { params: { id: 'abc' } });
    expect(res.status).toBe(400);
  });

  it('존재하지 않는 id → 404 에러', async () => {
    // get이 undefined 반환하도록 재모킹
    const db = require('@/lib/db').default;
    const originalPrepare = db.prepare.bind(db);
    db.prepare = jest.fn().mockReturnValue({ get: jest.fn().mockReturnValue(undefined), all: jest.fn().mockReturnValue([]) });

    const req = makeRequest('9999');
    const res = await GET(req, { params: { id: '9999' } });
    expect(res.status).toBe(404);

    db.prepare = originalPrepare;
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import DynamicTable, { ColumnDef } from '@/components/DynamicTable';

interface TestRow {
  _id: string;
  name: string;
  value: string;
}

const columns: ColumnDef<TestRow>[] = [
  { key: 'name', label: '이름', type: 'text' },
  { key: 'value', label: '값', type: 'text' },
];

const mockRows: TestRow[] = [
  { _id: 'row1', name: '홍길동', value: '테스트1' },
  { _id: 'row2', name: '김철수', value: '테스트2' },
];

describe('DynamicTable 컴포넌트', () => {
  it('컬럼 헤더가 렌더링됨', () => {
    render(
      <DynamicTable
        columns={columns}
        rows={[]}
        onAddRow={jest.fn()}
        onDeleteRow={jest.fn()}
        onUpdateRow={jest.fn()}
      />
    );
    expect(screen.getByText('이름')).toBeInTheDocument();
    expect(screen.getByText('값')).toBeInTheDocument();
  });

  it('빈 rows일 때 emptyMessage 표시', () => {
    render(
      <DynamicTable
        columns={columns}
        rows={[]}
        onAddRow={jest.fn()}
        onDeleteRow={jest.fn()}
        onUpdateRow={jest.fn()}
        emptyMessage="데이터가 없습니다."
      />
    );
    expect(screen.getByText('데이터가 없습니다.')).toBeInTheDocument();
  });

  it('행 추가 버튼 클릭 시 onAddRow 호출', () => {
    const onAddRow = jest.fn();
    render(
      <DynamicTable
        columns={columns}
        rows={[]}
        onAddRow={onAddRow}
        onDeleteRow={jest.fn()}
        onUpdateRow={jest.fn()}
        addLabel="+ 행 추가"
      />
    );
    fireEvent.click(screen.getByText('+ 행 추가'));
    expect(onAddRow).toHaveBeenCalledTimes(1);
  });

  it('rows가 있을 때 데이터가 렌더링됨', () => {
    render(
      <DynamicTable
        columns={columns}
        rows={mockRows}
        onAddRow={jest.fn()}
        onDeleteRow={jest.fn()}
        onUpdateRow={jest.fn()}
      />
    );
    const inputs = screen.getAllByDisplayValue('홍길동');
    expect(inputs.length).toBeGreaterThan(0);
  });

  it('삭제 버튼 클릭 시 onDeleteRow가 해당 _id로 호출', () => {
    const onDeleteRow = jest.fn();
    render(
      <DynamicTable
        columns={columns}
        rows={mockRows}
        onAddRow={jest.fn()}
        onDeleteRow={onDeleteRow}
        onUpdateRow={jest.fn()}
      />
    );
    const deleteButtons = screen.getAllByTitle('행 삭제');
    fireEvent.click(deleteButtons[0]);
    expect(onDeleteRow).toHaveBeenCalledWith('row1');
  });

  it('셀 값 변경 시 onUpdateRow 호출', () => {
    const onUpdateRow = jest.fn();
    render(
      <DynamicTable
        columns={columns}
        rows={mockRows}
        onAddRow={jest.fn()}
        onDeleteRow={jest.fn()}
        onUpdateRow={onUpdateRow}
      />
    );
    const inputs = screen.getAllByDisplayValue('홍길동');
    fireEvent.change(inputs[0], { target: { value: '이영희' } });
    expect(onUpdateRow).toHaveBeenCalledWith('row1', 'name', '이영희');
  });

  it('select 타입 컬럼 렌더링', () => {
    const columnsWithSelect: ColumnDef<{ _id: string; status: string }>[] = [
      { key: 'status', label: '상태', type: 'select', options: ['A', 'B', 'C'] },
    ];
    render(
      <DynamicTable
        columns={columnsWithSelect}
        rows={[{ _id: 'r1', status: 'A' }]}
        onAddRow={jest.fn()}
        onDeleteRow={jest.fn()}
        onUpdateRow={jest.fn()}
      />
    );
    expect(screen.getByDisplayValue('A')).toBeInTheDocument();
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import CandidateForm, { CandidateRow } from '@/components/CandidateForm';

const mockCandidate: CandidateRow = {
  _id: 'cand1',
  name: '김후보',
  birth_year: '1990',
  current_affiliation: 'KAIST',
  current_position: '조교수',
  major_field: '컴퓨터공학',
  total_papers: '30',
  jcr_ratio: '15',
  fwci: '2.0',
  remarks: '',
  degrees: [],
  careers: [],
};

describe('CandidateForm 컴포넌트', () => {
  it('후보자가 없을 때 "후보자가 없습니다." 메시지 표시', () => {
    render(<CandidateForm candidates={[]} onCandidatesChange={jest.fn()} />);
    expect(screen.getByText('후보자가 없습니다. 후보자를 추가해주세요.')).toBeInTheDocument();
  });

  it('후보자 추가 버튼 클릭 시 onCandidatesChange 호출', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[]} onCandidatesChange={onChange} />);
    fireEvent.click(screen.getByText('+ 후보자 추가'));
    expect(onChange).toHaveBeenCalledTimes(1);
    const newCandidates = onChange.mock.calls[0][0];
    expect(newCandidates).toHaveLength(1);
    expect(newCandidates[0]).toHaveProperty('name', '');
  });

  it('후보자가 있을 때 이름이 input에 표시됨', () => {
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={jest.fn()} />);
    const inputs = screen.getAllByDisplayValue('김후보');
    expect(inputs.length).toBeGreaterThan(0);
  });

  it('후보자 삭제 버튼 클릭 시 해당 후보자 제거', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={onChange} />);
    const deleteButtons = screen.getAllByTitle('행 삭제');
    fireEvent.click(deleteButtons[0]);
    expect(onChange).toHaveBeenCalledWith([]);
  });

  it('학위/경력 아코디언: 클릭하면 학위 섹션이 표시됨', () => {
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={jest.fn()} />);
    const accordionButton = screen.getByText(/김후보/);
    fireEvent.click(accordionButton);
    expect(screen.getByText('최종학위')).toBeInTheDocument();
    expect(screen.getByText('경력 사항')).toBeInTheDocument();
  });

  it('아코디언 다시 클릭하면 닫힘', () => {
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={jest.fn()} />);
    const accordionButton = screen.getByText(/김후보/);
    fireEvent.click(accordionButton);
    expect(screen.getByText('최종학위')).toBeInTheDocument();
    fireEvent.click(accordionButton);
    expect(screen.queryByText('최종학위')).not.toBeInTheDocument();
  });

  it('아코디언 열린 후 학위 추가 버튼 클릭', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={onChange} />);
    fireEvent.click(screen.getByText(/김후보/));
    fireEvent.click(screen.getByText('+ 학위 추가'));
    expect(onChange).toHaveBeenCalled();
    const updated = onChange.mock.calls[onChange.mock.calls.length - 1][0] as CandidateRow[];
    expect(updated[0].degrees).toHaveLength(1);
  });

  it('아코디언 열린 후 경력 추가 버튼 클릭', () => {
    const onChange = jest.fn();
    render(<CandidateForm candidates={[mockCandidate]} onCandidatesChange={onChange} />);
    fireEvent.click(screen.getByText(/김후보/));
    fireEvent.click(screen.getByText('+ 경력 추가'));
    expect(onChange).toHaveBeenCalled();
    const updated = onChange.mock.calls[onChange.mock.calls.length - 1][0] as CandidateRow[];
    expect(updated[0].careers).toHaveLength(1);
  });

  it('여러 후보자가 있을 때 각 후보자 이름 표시', () => {
    const candidates = [
      { ...mockCandidate, _id: 'c1', name: '후보자A' },
      { ...mockCandidate, _id: 'c2', name: '후보자B' },
    ];
    render(<CandidateForm candidates={candidates} onCandidatesChange={jest.fn()} />);
    expect(screen.getAllByDisplayValue('후보자A').length).toBeGreaterThan(0);
    expect(screen.getAllByDisplayValue('후보자B').length).toBeGreaterThan(0);
  });
});

